WITH sales_with_address AS (SELECT cs.cs_order_number, cs.cs_net_profit, ca_bill.ca_city AS bill_city, ca_ship.ca_city AS ship_city, i.i_category, sm.sm_type FROM catalog_sales cs JOIN customer_address ca_bill ON cs.cs_bill_addr_sk = ca_bill.ca_address_sk JOIN customer_address ca_ship ON cs.cs_ship_addr_sk = ca_ship.ca_address_sk JOIN item i ON cs.cs_item_sk = i.i_item_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk WHERE cs.cs_sold_date_sk BETWEEN 20200101 AND 20200131) SELECT bill_city, i_category, sm_type, total_profit, CASE WHEN total_profit > 10000 THEN 'High' WHEN total_profit > 5000 THEN 'Medium' ELSE 'Low' END AS profit_level, RANK() OVER (ORDER BY total_profit DESC) AS profit_rank FROM (SELECT bill_city, i_category, sm_type, SUM(cs_net_profit) AS total_profit FROM sales_with_address GROUP BY bill_city, i_category, sm_type) agg ORDER BY total_profit DESC LIMIT 10
